<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>Maze Discovery — 24 Explorer Bots</title>
<style>
  :root{
    --bg:#0e1116; --panel:#161b22; --line:#30363d; --ink:#e6edf3; --dim:#8b949e;
    --accent:#58a6ff;
  }
  *{box-sizing:border-box}
  html,body{margin:0;padding:0}
  body{
    background:var(--bg); color:var(--ink);
    font:14px/1.45 ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;
    display:flex; flex-direction:column; align-items:center; gap:14px; padding:18px;
  }
  h1{font-size:16px;font-weight:600;letter-spacing:.04em;margin:0;color:var(--dim)}
  #hud{
    display:flex; gap:10px; align-items:center; flex-wrap:wrap; justify-content:center;
    background:var(--panel); border:1px solid var(--line); border-radius:10px; padding:10px 14px;
  }
  .stat{display:flex;flex-direction:column;align-items:center;min-width:88px}
  .stat .k{font-size:10px;letter-spacing:.12em;text-transform:uppercase;color:var(--dim)}
  .stat .v{font-size:20px;font-weight:700;font-variant-numeric:tabular-nums}
  .v.done{color:#3fb950}
  button{
    font:inherit; font-weight:600; color:#fff; background:#1f6feb; border:1px solid #388bfd;
    border-radius:8px; padding:8px 14px; cursor:pointer;
  }
  button:hover{background:#2a7bf6}
  button.alt{background:#21262d;border-color:var(--line);color:var(--ink)}
  #maze{
    background:var(--panel); border:1px solid var(--line); border-radius:10px;
    padding:10px; line-height:0;
  }
  canvas{display:block;border-radius:4px}
  #note{color:var(--dim);font-size:11px;max-width:520px;text-align:center}
</style>
</head>
<body>

<h1>MAZE DISCOVERY — 24 TREMAUX/DFS EXPLORERS</h1>

<div id="hud">
  <div class="stat"><span class="k">Completed</span><span class="v" id="completed">0 / 24</span></div>
  <div class="stat"><span class="k">Timer (ticks)</span><span class="v" id="timer">0</span></div>
  <button id="reset">Reset</button>
  <button id="pause" class="alt">Pause</button>
  <button id="step" class="alt">Step</button>
</div>

<div id="maze"></div>

<div id="note">
  Every bot knows only the cell it stands in. It senses walls locally, pushes new cells on its own
  stack, and on a dead end or exhausted branch it marks the cell dead and backtracks — so no passage
  is walked more than twice by the same bot. 24 distinct direction preferences spread them out.
</div>

<script>
(function(){
"use strict";

/* ------------------------------------------------------------------ *
 * seeded rng
 * ------------------------------------------------------------------ */
function mulberry32(a){
  a = a|0;
  return function(){
    a = (a + 0x6D2B79F5)|0;
    var t = Math.imul(a ^ (a>>>15), 1|a);
    t = (t + Math.imul(t ^ (t>>>7), 61|t)) ^ t;
    return ((t ^ (t>>>14))>>>0) / 4294967296;
  };
}

/* ------------------------------------------------------------------ *
 * constants
 * ------------------------------------------------------------------ */
var ROWS = 21, COLS = 21, NBOTS = 24;
var CELL = 22, PAD = 12;                 // 21*22 + 24 = 486px canvas  (>= 400)
var TICK_MS = 120;                        // wall-clock pacing of the animation

// direction indices: 0=N 1=E 2=S 3=W
var DR = [-1, 0, 1, 0], DC = [0, 1, 0, -1];
var WALLKEY = ["n","e","s","w"];
var OPP = [2,3,0,1];

// the 24 permutations of 4 directions, in fixed lexicographic order:
// one distinct exploration preference per bot.
var PERMS = (function(){
  var out = [];
  (function rec(rest, acc){
    if(!rest.length){ out.push(acc.slice()); return; }
    for(var i=0;i<rest.length;i++){
      var next = rest.slice(); next.splice(i,1);
      rec(next, acc.concat(rest[i]));
    }
  })([0,1,2,3], []);
  return out;                            // exactly 24
})();

var COLORS = (function(){
  var c = [];
  for(var i=0;i<NBOTS;i++){
    var h = Math.round(i * (360/NBOTS));
    var l = (i % 2 === 0) ? 62 : 48;
    c.push("hsl(" + h + "," + (i%3===0?92:76) + "%," + l + "%)");
  }
  return c;
})();

/* ------------------------------------------------------------------ *
 * maze generation — randomised DFS carve => perfect maze
 * ------------------------------------------------------------------ */
function key(r,c){ return r * COLS + c; }
function inBounds(r,c){ return r>=0 && r<ROWS && c>=0 && c<COLS; }

function buildMaze(seed){
  var rnd = mulberry32(seed >>> 0);
  var cells = new Array(ROWS*COLS);
  for(var i=0;i<cells.length;i++) cells[i] = {n:true,e:true,s:true,w:true};

  var seen = new Uint8Array(ROWS*COLS);
  var stack = [{r:0,c:0}];
  seen[0] = 1;

  while(stack.length){
    var cur = stack[stack.length-1];
    var opts = [];
    for(var d=0; d<4; d++){
      var nr = cur.r + DR[d], nc = cur.c + DC[d];
      if(inBounds(nr,nc) && !seen[key(nr,nc)]) opts.push(d);
    }
    if(!opts.length){ stack.pop(); continue; }
    var pick = opts[Math.floor(rnd() * opts.length) % opts.length];
    var nr2 = cur.r + DR[pick], nc2 = cur.c + DC[pick];
    cells[key(cur.r,cur.c)][WALLKEY[pick]] = false;
    cells[key(nr2,nc2)][WALLKEY[OPP[pick]]] = false;
    seen[key(nr2,nc2)] = 1;
    stack.push({r:nr2,c:nc2});
  }
  return cells;
}

/* ------------------------------------------------------------------ *
 * bot — purely local depth-first (Tremaux) exploration
 * ------------------------------------------------------------------ *
 * A bot only ever inspects walls of the cell it currently occupies.
 * It keeps its own visited set + its own stack; nothing global, no
 * BFS/A*, no knowledge of the exit until it steps onto it.
 * ------------------------------------------------------------------ */
function Bot(id, spawn){
  this.id = id;
  this.order = PERMS[id % PERMS.length];
  this.color = COLORS[id % COLORS.length];

  this.r = spawn.r; this.c = spawn.c;
  this.pr = spawn.r; this.pc = spawn.c;      // previous cell (for interpolation)

  this.visited = new Set([key(spawn.r, spawn.c)]);
  this.dead = new Set();
  this.stack = [{r:spawn.r, c:spawn.c}];

  this.path = [{r:spawn.r, c:spawn.c}];
  this.deadEnds = [];
  this.finishTick = null;
  this.stuck = false;
}

Bot.prototype.step = function(state, tickNo){
  if(this.finishTick !== null || this.stuck) return;

  var cell = state.cells[key(this.r, this.c)];   // local sensing only
  var d, i, nr, nc;

  // 1. any open neighbour this bot has never entered? -> go deeper
  for(i=0; i<4; i++){
    d = this.order[i];
    if(cell[WALLKEY[d]]) continue;               // wall: not a passage
    nr = this.r + DR[d]; nc = this.c + DC[d];
    if(!inBounds(nr,nc)) continue;
    if(this.visited.has(key(nr,nc))) continue;   // already known to me
    this.moveTo(nr, nc, state, tickNo, true);
    return;
  }

  // 2. nothing new here: this branch is exhausted -> mark dead, backtrack
  if(!this.dead.has(key(this.r,this.c))){
    this.dead.add(key(this.r,this.c));
    this.deadEnds.push({r:this.r, c:this.c});
  }
  this.stack.pop();
  if(!this.stack.length){ this.stuck = true; return; }   // whole maze exhausted
  var back = this.stack[this.stack.length-1];
  this.moveTo(back.r, back.c, state, tickNo, false);
};

Bot.prototype.moveTo = function(nr, nc, state, tickNo, forward){
  this.pr = this.r; this.pc = this.c;
  this.r = nr; this.c = nc;
  if(forward){
    this.visited.add(key(nr,nc));
    this.stack.push({r:nr, c:nc});
  }
  this.path.push({r:nr, c:nc});
  if(nr === state.exit.r && nc === state.exit.c && this.finishTick === null){
    this.finishTick = tickNo;                    // arrives -> stops here forever
  }
};

/* ------------------------------------------------------------------ *
 * simulation state
 * ------------------------------------------------------------------ */
var state = null;
var seedCounter = 1;

function makeState(seed){
  var s = {
    seed: seed >>> 0,
    cells: buildMaze(seed),
    spawn: {r:0, c:0},
    exit:  {r:ROWS-1, c:COLS-1},
    elapsed: 0,
    bots: []
  };
  for(var i=0;i<NBOTS;i++) s.bots.push(new Bot(i, s.spawn));
  return s;
}

function allDone(s){
  for(var i=0;i<s.bots.length;i++){
    var b = s.bots[i];
    if(b.finishTick === null && !b.stuck) return false;
  }
  return true;
}

function completedCount(s){
  var n = 0;
  for(var i=0;i<s.bots.length;i++) if(s.bots[i].finishTick !== null) n++;
  return n;
}

// one atomic tick. Frozen once every bot has arrived: elapsed never moves again.
function stepOnce(){
  if(allDone(state)) return false;
  state.elapsed += 1;
  var t = state.elapsed;
  for(var i=0;i<state.bots.length;i++) state.bots[i].step(state, t);
  return true;
}

function tick(n){
  n = (n === undefined) ? 1 : Math.floor(n);
  if(!(n > 0)) { renderHud(); return; }
  for(var i=0;i<n;i++){
    if(!stepOnce()) break;
  }
  interp = 1;                 // programmatic ticks land bots exactly on-cell
  renderHud();
  draw();
}

function reset(seed){
  if(typeof seed === "number" && isFinite(seed)) seed = seed >>> 0;
  else seed = (seedCounter = (seedCounter * 1103515245 + 12345) >>> 0);
  state = makeState(seed);
  interp = 1; acc = 0;
  window.game.size  = {rows:ROWS, cols:COLS};
  window.game.spawn = {r:state.spawn.r, c:state.spawn.c};
  window.game.exit  = {r:state.exit.r,  c:state.exit.c};
  window.game.bots  = state.bots;
  renderHud();
  draw();
}

/* ------------------------------------------------------------------ *
 * rendering
 * ------------------------------------------------------------------ */
var mazeEl = document.getElementById("maze");
var canvas = document.createElement("canvas");
canvas.width  = COLS * CELL + PAD * 2;
canvas.height = ROWS * CELL + PAD * 2;
canvas.style.width  = canvas.width + "px";
canvas.style.height = canvas.height + "px";
mazeEl.appendChild(canvas);
var ctx = canvas.getContext("2d");

var interp = 1;     // 0..1 fraction between previous and current cell
var acc = 0;        // wall-clock accumulator
var running = true;

function cx(c){ return PAD + c * CELL + CELL/2; }
function cy(r){ return PAD + r * CELL + CELL/2; }

function draw(){
  var W = canvas.width, H = canvas.height;
  ctx.fillStyle = "#0b0e13";
  ctx.fillRect(0,0,W,H);

  // exit + spawn tiles
  ctx.fillStyle = "rgba(63,185,80,.28)";
  ctx.fillRect(PAD + state.exit.c*CELL + 2, PAD + state.exit.r*CELL + 2, CELL-4, CELL-4);
  ctx.fillStyle = "rgba(88,166,255,.20)";
  ctx.fillRect(PAD + state.spawn.c*CELL + 2, PAD + state.spawn.r*CELL + 2, CELL-4, CELL-4);

  // walls
  ctx.strokeStyle = "#c9d1d9";
  ctx.lineWidth = 2;
  ctx.lineCap = "square";
  ctx.beginPath();
  for(var r=0;r<ROWS;r++){
    for(var c=0;c<COLS;c++){
      var cell = state.cells[key(r,c)];
      var x = PAD + c*CELL, y = PAD + r*CELL;
      if(cell.n){ ctx.moveTo(x, y);            ctx.lineTo(x+CELL, y); }
      if(cell.w){ ctx.moveTo(x, y);            ctx.lineTo(x, y+CELL); }
      if(cell.s){ ctx.moveTo(x, y+CELL);       ctx.lineTo(x+CELL, y+CELL); }
      if(cell.e){ ctx.moveTo(x+CELL, y);       ctx.lineTo(x+CELL, y+CELL); }
    }
  }
  ctx.stroke();

  // exit marker
  ctx.fillStyle = "#3fb950";
  ctx.font = "bold 12px ui-monospace,monospace";
  ctx.textAlign = "center"; ctx.textBaseline = "middle";
  ctx.fillText("E", cx(state.exit.c), cy(state.exit.r));
  ctx.fillStyle = "#58a6ff";
  ctx.fillText("S", cx(state.spawn.c), cy(state.spawn.r));

  // bots — interpolated between previous and current cell, corridor-centred
  var t = interp < 0 ? 0 : (interp > 1 ? 1 : interp);
  var e = t*t*(3 - 2*t);                      // smoothstep
  var rad = CELL * 0.27;
  for(var i=0;i<state.bots.length;i++){
    var b = state.bots[i];
    var bx, by;
    if(b.finishTick !== null){
      // parked at the exit, fanned out slightly so all 24 stay visible
      var a = (i / NBOTS) * Math.PI * 2;
      bx = cx(b.c) + Math.cos(a) * CELL * 0.26;
      by = cy(b.r) + Math.sin(a) * CELL * 0.26;
      rad = CELL * 0.13;
    } else {
      rad = CELL * 0.27;
      bx = cx(b.pc) + (cx(b.c) - cx(b.pc)) * e;
      by = cy(b.pr) + (cy(b.r) - cy(b.pr)) * e;
    }
    ctx.beginPath();
    ctx.arc(bx, by, rad, 0, Math.PI*2);
    ctx.fillStyle = b.color;
    ctx.fill();
    ctx.lineWidth = 1;
    ctx.strokeStyle = "rgba(0,0,0,.55)";
    ctx.stroke();
  }
}

var elCompleted = document.getElementById("completed");
var elTimer     = document.getElementById("timer");

function renderHud(){
  var done = completedCount(state);
  elCompleted.textContent = done + " / " + NBOTS;
  elCompleted.className = "v" + (done === NBOTS ? " done" : "");
  elTimer.textContent = String(state.elapsed);
  elTimer.className = "v" + (allDone(state) ? " done" : "");
}

/* ------------------------------------------------------------------ *
 * animation loop (pure presentation — never affects determinism)
 * ------------------------------------------------------------------ */
var last = null;
function frame(now){
  if(last === null) last = now;
  var dt = now - last; last = now;
  if(dt > 250) dt = 250;

  if(running && !allDone(state)){
    acc += dt;
    while(acc >= TICK_MS){
      acc -= TICK_MS;
      stepOnce();
      renderHud();
    }
    interp = allDone(state) ? 1 : (acc / TICK_MS);
  }
  draw();
  requestAnimationFrame(frame);
}

/* ------------------------------------------------------------------ *
 * controls
 * ------------------------------------------------------------------ */
document.getElementById("reset").addEventListener("click", function(){ reset(); });

var pauseBtn = document.getElementById("pause");
pauseBtn.addEventListener("click", function(){
  running = !running;
  pauseBtn.textContent = running ? "Pause" : "Play";
});
document.getElementById("step").addEventListener("click", function(){ tick(1); });

/* ------------------------------------------------------------------ *
 * public scripting API
 * ------------------------------------------------------------------ */
window.game = {
  tick: tick,
  reset: reset,
  get elapsed(){ return state.elapsed; },
  size: {rows:ROWS, cols:COLS},
  spawn: {r:0, c:0},
  exit: {r:ROWS-1, c:COLS-1},
  walls: function(r,c){
    if(!inBounds(r,c)) return {n:true,e:true,s:true,w:true};
    var w = state.cells[key(r,c)];
    return {n:w.n, e:w.e, s:w.s, w:w.w};
  },
  get bots(){ return state.bots; }
};

reset(20260727);
requestAnimationFrame(frame);

})();
</script>
</body>
</html>
